import json
from collections import Counter
import statistics

with open('/root/trace_distill_repair/pipeline_output/phase3_checkpoint.json') as f:
    data = json.load(f)

subset_a = {'black_1', 'cookiecutter_1', 'cookiecutter_2', 'cookiecutter_3', 'fastapi_1', 'fastapi_2', 'luigi_5', 'sanic_2', 'scrapy_2', 'scrapy_7', 'tornado_2', 'youtube-dl_1', 'youtube-dl_2', 'youtube-dl_5', 'youtube-dl_20'}
subset_b = {'httpie_1', 'httpie_2', 'luigi_1', 'luigi_2', 'luigi_10', 'luigi_14', 'sanic_1', 'scrapy_1', 'scrapy_3', 'scrapy_4', 'thefuck_1', 'thefuck_2', 'thefuck_4', 'tornado_1', 'tornado_4', 'tornado_5', 'tornado_7', 'youtube-dl_10'}

conditions = ['no_trace', 'full_trace', 'structural_filtered', 'line_filtered']

lookup = {}
for inst_id, records in data.items():
    lookup[inst_id] = {}
    for r in records:
        lookup[inst_id][r['condition']] = r

all_instances = sorted(lookup.keys())
print(f"Total instances: {len(all_instances)}")
print(f"Subset A: {len(subset_a & set(all_instances))}/{len(subset_a)}")
print(f"Subset B: {len(subset_b & set(all_instances))}/{len(subset_b)}")
print()

print("=" * 70)
print("ANALYSIS 1: Judge Score Comparison")
print("=" * 70)

for cond in conditions:
    scores = []
    for inst_id in all_instances:
        if cond in lookup[inst_id]:
            s = lookup[inst_id][cond].get('llm_judge_score')
            if s is not None:
                scores.append(s)
    dist = Counter(scores)
    mean_s = statistics.mean(scores) if scores else 0
    median_s = statistics.median(scores) if scores else 0
    gte4 = sum(1 for s in scores if s >= 4)
    print(f"\n{cond} (n={len(scores)}):")
    print(f"  Distribution: " + ", ".join(f"{k}:{dist.get(k,0)}" for k in range(6)))
    print(f"  Mean={mean_s:.2f}, Median={median_s:.1f}, Judge>=4: {gte4}/{len(scores)} ({100*gte4/len(scores):.1f}%)")

print(f"\nHead-to-head: structural_filtered vs line_filtered")
wins, ties, losses = 0, 0, 0
details = []
for inst_id in all_instances:
    s_score = lookup[inst_id].get('structural_filtered', {}).get('llm_judge_score')
    l_score = lookup[inst_id].get('line_filtered', {}).get('llm_judge_score')
    if s_score is not None and l_score is not None:
        if s_score > l_score:
            wins += 1
            details.append(f"  WIN  {inst_id}: struct={s_score} > line={l_score}")
        elif s_score == l_score:
            ties += 1
        else:
            losses += 1
            details.append(f"  LOSS {inst_id}: struct={s_score} < line={l_score}")
print(f"  Structural wins: {wins}, Ties: {ties}, Line wins: {losses}")
if wins + losses > 0:
    print(f"  Win rate (excl ties): {wins}/{wins+losses} = {100*wins/(wins+losses):.1f}%")
for d in details:
    print(d)

print("\n" + "=" * 70)
print("ANALYSIS 2: Stratified Analysis")
print("=" * 70)

for subset_name, subset_ids in [("Subset A (structural keep>0)", subset_a), ("Subset B (structural keep=0)", subset_b)]:
    print(f"\n--- {subset_name} ---")
    active_ids = sorted(subset_ids & set(all_instances))
    for cond in conditions:
        scores = []
        for inst_id in active_ids:
            if cond in lookup[inst_id]:
                s = lookup[inst_id][cond].get('llm_judge_score')
                if s is not None:
                    scores.append(s)
        if scores:
            mean_s = statistics.mean(scores)
            median_s = statistics.median(scores)
            gte4 = sum(1 for s in scores if s >= 4)
            print(f"  {cond:25s}: mean={mean_s:.2f}, median={median_s:.1f}, >=4: {gte4}/{len(scores)} ({100*gte4/len(scores):.1f}%)")
        else:
            print(f"  {cond:25s}: no data")
    sw, st, sl = 0, 0, 0
    for inst_id in active_ids:
        ss = lookup[inst_id].get('structural_filtered', {}).get('llm_judge_score')
        ls = lookup[inst_id].get('line_filtered', {}).get('llm_judge_score')
        if ss is not None and ls is not None:
            if ss > ls: sw += 1
            elif ss == ls: st += 1
            else: sl += 1
    print(f"  struct vs line H2H: wins={sw}, ties={st}, losses={sl}")

print("\n" + "=" * 70)
print("ANALYSIS 3: Token Efficiency")
print("=" * 70)

for cond in conditions:
    tokens = []
    for inst_id in all_instances:
        if cond in lookup[inst_id]:
            t = lookup[inst_id][cond].get('tokens_input')
            if t is not None:
                tokens.append(t)
    mean_t = statistics.mean(tokens) if tokens else 0
    print(f"  {cond:25s}: mean_input_tokens={mean_t:.0f} (n={len(tokens)})")

print(f"\n  Among judge>=4 instances:")
for cond in ['structural_filtered', 'line_filtered']:
    tokens_good = []
    for inst_id in all_instances:
        rec = lookup[inst_id].get(cond, {})
        if rec.get('llm_judge_score', 0) >= 4:
            t = rec.get('tokens_input')
            if t is not None:
                tokens_good.append(t)
    if tokens_good:
        print(f"    {cond}: mean_input_tokens={statistics.mean(tokens_good):.0f}, n={len(tokens_good)}")
    else:
        print(f"    {cond}: no instances with judge>=4")

print("\n" + "=" * 70)
print("ANALYSIS 4: Exact Match + Line Overlap")
print("=" * 70)

for cond in conditions:
    exact = 0
    overlap_gt50 = 0
    overlaps = []
    n = 0
    for inst_id in all_instances:
        rec = lookup[inst_id].get(cond, {})
        if rec:
            n += 1
            if rec.get('exact_match') or rec.get('repair_success'):
                exact += 1
            lo = rec.get('line_overlap')
            if lo is not None:
                overlaps.append(lo)
                if lo > 0.5:
                    overlap_gt50 += 1
    mean_lo = statistics.mean(overlaps) if overlaps else 0
    print(f"  {cond:25s}: exact/success={exact}/{n}, line_overlap>0.5: {overlap_gt50}/{len(overlaps)}, mean_overlap={mean_lo:.3f}")

print("\n" + "=" * 70)
print("ANALYSIS 5: MVP Judgment (full_trace tokens > 2K)")
print("=" * 70)

large_trace_ids = []
for inst_id in all_instances:
    ft_rec = lookup[inst_id].get('full_trace', {})
    ft_tokens = ft_rec.get('tokens_input', 0)
    if ft_tokens > 2000:
        large_trace_ids.append(inst_id)

print(f"  Large trace instances (full_trace input > 2K tokens): {len(large_trace_ids)}/{len(all_instances)}")
print(f"  Instances: {', '.join(large_trace_ids)}")

sw, st, sl = 0, 0, 0
details5 = []
for inst_id in large_trace_ids:
    ss = lookup[inst_id].get('structural_filtered', {}).get('llm_judge_score')
    ls = lookup[inst_id].get('line_filtered', {}).get('llm_judge_score')
    ft = lookup[inst_id].get('full_trace', {}).get('tokens_input', 0)
    if ss is not None and ls is not None:
        if ss > ls:
            sw += 1
            details5.append(f"  WIN  {inst_id}: struct={ss} vs line={ls} (full_trace={ft} tok)")
        elif ss == ls:
            st += 1
            details5.append(f"  TIE  {inst_id}: struct={ss} vs line={ls} (full_trace={ft} tok)")
        else:
            sl += 1
            details5.append(f"  LOSS {inst_id}: struct={ss} vs line={ls} (full_trace={ft} tok)")

total_decided = sw + sl
print(f"  structural vs line H2H: wins={sw}, ties={st}, losses={sl}")
if total_decided > 0:
    print(f"  Win rate (excl ties): {sw}/{total_decided} = {100*sw/total_decided:.1f}%")
for d in details5:
    print(d)

print(f"\n  All conditions on large-trace subset:")
for cond in conditions:
    scores = []
    for inst_id in large_trace_ids:
        s = lookup[inst_id].get(cond, {}).get('llm_judge_score')
        if s is not None:
            scores.append(s)
    mean_s = statistics.mean(scores) if scores else 0
    gte4 = sum(1 for s in scores if s >= 4)
    print(f"    {cond:25s}: mean={mean_s:.2f}, >=4: {gte4}/{len(scores)}")

print(f"\n  Token savings (large-trace subset):")
for cond in ['structural_filtered', 'line_filtered']:
    savings = []
    for inst_id in large_trace_ids:
        ft_tok = lookup[inst_id].get('full_trace', {}).get('tokens_input', 0)
        c_tok = lookup[inst_id].get(cond, {}).get('tokens_input', 0)
        if ft_tok > 0 and c_tok > 0:
            savings.append(1 - c_tok / ft_tok)
    mean_sav = statistics.mean(savings) if savings else 0
    print(f"    {cond}: mean token reduction={100*mean_sav:.1f}%")

